(1440629, 186916, 327, '<td valign="top">How beautiful. Would like to be there.</td>', 'How beautiful. Would like to be there.', '2005-06-08 09:44:59.000000', NULL, 1),
(1440632, 185159, 35548, '<td valign="top">Depth of field problems could be solved with better lighting.</td>', 'Depth of field problems could be solved with better lighting.', '2005-06-08 09:49:07.000000', NULL, 1),
(1440638, 185594, 35548, '<td valign="top">Image seems to be out of focus.</td>', 'Image seems to be out of focus.', '2005-06-08 09:54:15.000000', NULL, 1),
(1440649, 186876, 23053, '<td valign="top">Fotoshootme, this is quite nice.  The detail and tonal qualities are very attractive, and I get the sense that your subject is certainly overworked and tired.  While I know that the welding helmet is part of his equipment, it is a slightly odd element in the photo.  Overall, I expect this shot to place very well.</td>', 'Fotoshootme, this is quite nice.  The detail and tonal qualities are very attractive, and I get the sense that your subject is certainly overworked and tired.  While I know that the welding helmet is part of his equipment, it is a slightly odd element in the photo.  Overall, I expect this shot to place very well.', '2005-06-08 10:02:22.000000', NULL, 1),
(1440662, 186610, 35548, '<td valign="top">Depth of field problem, more light equel smallier apreture= more object in focus in foreground and background.</td>', 'Depth of field problem, more light equel smallier apreture= more object in focus in foreground and background.', '2005-06-08 10:09:54.000000', NULL, 1),
(1440673, 186792, 15711, '<td valign="top">This is is really a good photo!!  Silhouettes are always so interesting, particularly this one with the nice clouds and colors behind!!</td>', 'This is is really a good photo!!  Silhouettes are always so interesting, particularly this one with the nice clouds and colors behind!!', '2005-06-08 10:13:38.000000', NULL, 1),
