(1442839, 184731, 28742, '<td valign="top">looking... looking... hmmm. No construction going on here. :(</td>', 'looking... looking... hmmm. No construction going on here. :(', '2005-06-09 01:16:09.000000', NULL, 1),
(1442840, 186625, 28742, '<td valign="top">Where''s their little orange vests? :P<br/>A great macro! Fits the challenge well also. Good job!</td>', 'Where''s their little orange vests? :PA great macro! Fits the challenge well also. Good job!', '2005-06-09 01:17:33.000000', NULL, 1),
(1442842, 186880, 28742, '<td valign="top">Color, tones, lighting - all oustanding. Fits challenge. Good focus &amp; composition - but faces seem like they would have really helped. All in all, excellent work.</td>', 'Color, tones, lighting - all oustanding. Fits challenge. Good focus & composition - but faces seem like they would have really helped. All in all, excellent work.', '2005-06-09 01:19:37.000000', NULL, 1),
(1442843, 186882, 28742, '<td valign="top">Looks more like noituac. ;-)</td>', 'Looks more like noituac. ;-)', '2005-06-09 01:20:20.000000', NULL, 1),
(1442845, 185342, 28742, '<td valign="top">Way too much sky for my liking.</td>', 'Way too much sky for my liking.', '2005-06-09 01:21:09.000000', NULL, 1),
(1442846, 186901, 28742, '<td valign="top">LOL! I would give you a humor point if the picture was lousy, but it is actually very well done! Good dof, great color, cute factor - I''ll give it a 7 and throw in the humor point for an 8. Well done and good luck.</td>', 'LOL! I would give you a humor point if the picture was lousy, but it is actually very well done! Good dof, great color, cute factor - I''ll give it a 7 and throw in the humor point for an 8. Well done and good luck.', '2005-06-09 01:24:00.000000', NULL, 1),
(1442849, 186744, 28742, '<td valign="top">Good job on this. Although I have never seen anyone swing a hammer with their finger extended like that. Colors and focus good.</td>', 'Good job on this. Although I have never seen anyone swing a hammer with their finger extended like that. Colors and focus good.', '2005-06-09 01:27:52.000000', NULL, 1),
(1442851, 186955, 28742, '<td valign="top">That seems bizarre from a construction standpoint. From a photographic view - it''s excellent. Should do very well!</td>', 'That seems bizarre from a construction standpoint. From a photographic view - it''s excellent. Should do very well!', '2005-06-09 01:29:23.000000', NULL, 1),
(1442855, 186445, 28742, '<td valign="top">I thought it was already built? Are they just shining it up? But then it wouldn''t be "Construction" would it? ...I''ll give you the benefit of the doubt since it is probably the best image I''ve seen in the challenge so far. Good luck!</td>', 'I thought it was already built? Are they just shining it up? But then it wouldn''t be "Construction" would it? ...I''ll give you the benefit of the doubt since it is probably the best image I''ve seen in the challenge so far. Good luck!', '2005-06-09 01:31:46.000000', NULL, 1),
(1442861, 186811, 28742, '<td valign="top">Hmmm. If the challenge were "Constructed" I would rank this high. Points for a good image, but I don''t feel the challenge connection enough.</td>', 'Hmmm. If the challenge were "Constructed" I would rank this high. Points for a good image, but I don''t feel the challenge connection enough.', '2005-06-09 01:33:29.000000', NULL, 1),
(1442862, 185205, 28742, '<td valign="top">Wow. Cool shot - very interesting. I like it.</td>', 'Wow. Cool shot - very interesting. I like it.', '2005-06-09 01:34:32.000000', NULL, 1),
(1442864, 186886, 772, '<td valign="top">Very nice use of wide angle...</td>', 'Very nice use of wide angle...', '2005-06-09 01:35:36.000000', NULL, 1),
(1442865, 186276, 28742, '<td valign="top">Hmmm, title is funny - if it''s true, I want some. ;-) Great shot and I think it will place in the top 10 at least. Good luck.</td>', 'Hmmm, title is funny - if it''s true, I want some. ;-) Great shot and I think it will place in the top 10 at least. Good luck.', '2005-06-09 01:36:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1442868, 186886, 28742, '<td valign="top">Fantastic! Very dramatic. A top pick.</td>', 'Fantastic! Very dramatic. A top pick.', '2005-06-09 01:38:54.000000', NULL, 1),
(1442872, 185256, 28742, '<td valign="top">Great shot! This is nearly perfect to me. There''s probably something wrong with it - but I can''t find it. :)</td>', 'Great shot! This is nearly perfect to me. There''s probably something wrong with it - but I can''t find it. :)', '2005-06-09 01:42:20.000000', NULL, 1),
(1442873, 186169, 28742, '<td valign="top">A bee building a hive I can take. This I just can''t. If it were for a butterfly challenge, I would give it a 6. Sorry.</td>', 'A bee building a hive I can take. This I just can''t. If it were for a butterfly challenge, I would give it a 6. Sorry.', '2005-06-09 01:44:14.000000', NULL, 1),
(1442876, 186574, 28742, '<td valign="top">I''m trying to find you in the reflection.... Red shirt?</td>', 'I''m trying to find you in the reflection.... Red shirt?', '2005-06-09 01:47:36.000000', NULL, 1),
(1442877, 186857, 28742, '<td valign="top">Could be a farming tractor. Very nice shot, but can''t make the construction connection unless I just assume that''s a construction vehicle. Only knock a point for that though. :)</td>', 'Could be a farming tractor. Very nice shot, but can''t make the construction connection unless I just assume that''s a construction vehicle. Only knock a point for that though. :)', '2005-06-09 01:48:56.000000', NULL, 1),
(1442889, 186878, 38799, '<td valign="top">i like it, i like how everything stands out, i give you a ten!!</td>', 'i like it, i like how everything stands out, i give you a ten!!', '2005-06-09 02:07:24.000000', NULL, 1),
(1442892, 186849, 37103, '<td valign="top">I like the composition and complementary colors in this image, the only thing that makes it less interesting is that there is not central focus.  You can''t see the guys face and there is no real attention grabber.</td>', 'I like the composition and complementary colors in this image, the only thing that makes it less interesting is that there is not central focus.  You can''t see the guys face and there is no real attention grabber.', '2005-06-09 02:13:33.000000', NULL, 1),
(1442893, 186811, 37103, '<td valign="top">I think this is a beautiful image.  I love the shades of blue, shadows and symmetry.  For me the only real negative is that I just don''t associate with construction, although it certainly was "constructed" by someone.</td>', 'I think this is a beautiful image.  I love the shades of blue, shadows and symmetry.  For me the only real negative is that I just don''t associate with construction, although it certainly was "constructed" by someone.', '2005-06-09 02:14:49.000000', NULL, 1),
(1442894, 186604, 37103, '<td valign="top">I can''t decide what to focus on in this photo and for me that detracts from it a bit.  The colors are great, although the green in the upper left is a little distracting, mostly because I can''t figure out what I''m seeing.</td>', 'I can''t decide what to focus on in this photo and for me that detracts from it a bit.  The colors are great, although the green in the upper left is a little distracting, mostly because I can''t figure out what I''m seeing.', '2005-06-09 02:16:07.000000', NULL, 1),
(1442896, 186878, 37103, '<td valign="top">I would like to see a little more detail in this photo, it seems a little out of focus.  It also seems a little red.</td>', 'I would like to see a little more detail in this photo, it seems a little out of focus.  It also seems a little red.', '2005-06-09 02:17:19.000000', NULL, 1),
(1442898, 186589, 37103, '<td valign="top">This is a really fun image, the title makes me laugh, his posture is great.  I would like to see a little more contrast to bring out the whites and blacks.</td>', 'This is a really fun image, the title makes me laugh, his posture is great.  I would like to see a little more contrast to bring out the whites and blacks.', '2005-06-09 02:18:32.000000', NULL, 1),
(1442899, 186838, 37103, '<td valign="top">For me the focus of the picture (the crane) is too far away here, it is hard for me to make out any details on it.  However, I like the fact that it puts construction in perspective, behind the forest.</td>', 'For me the focus of the picture (the crane) is too far away here, it is hard for me to make out any details on it.  However, I like the fact that it puts construction in perspective, behind the forest.', '2005-06-09 02:19:56.000000', NULL, 1),
(1442904, 185713, 19831, '<td valign="top">I like this shot. Composed nicely and an interesting capture. The man at an angle, the rebar, and the building in the background makes for nice lines and forms. Nice job.</td>', 'I like this shot. Composed nicely and an interesting capture. The man at an angle, the rebar, and the building in the background makes for nice lines and forms. Nice job.', '2005-06-09 02:34:44.000000', NULL, 1),
(1442905, 185891, 19831, '<td valign="top">Nice composition. Although the light seems blown out, it seems that that is perhaps your intent?, and I think it works in this photo. Very good use of leading lines and a vanishing point. Good job.</td>', 'Nice composition. Although the light seems blown out, it seems that that is perhaps your intent?, and I think it works in this photo. Very good use of leading lines and a vanishing point. Good job.', '2005-06-09 02:37:05.000000', NULL, 1),
(1442912, 186892, 19831, '<td valign="top">Interesting photo. I think most people would see a fence such as this as an obstruction or hinderance to trying to get their shot. I like how you''ve creatively  overcome that by using dof to incorporate it in your photo. The way you''ve done this, I feel like I am standing there at the fence looking through at this construction site. Very nice job.</td>', 'Interesting photo. I think most people would see a fence such as this as an obstruction or hinderance to trying to get their shot. I like how you''ve creatively  overcome that by using dof to incorporate it in your photo. The way you''ve done this, I feel like I am standing there at the fence looking through at this construction site. Very nice job.', '2005-06-09 02:44:30.000000', NULL, 1),
(1442913, 184969, 19831, '<td valign="top">Nice capture. I like the lines and shapes present in your composition.</td>', 'Nice capture. I like the lines and shapes present in your composition.', '2005-06-09 02:46:00.000000', NULL, 1),
(1442914, 186807, 19831, '<td valign="top">You''ve made a nice abstract here, IMO. Obviously nice lines, and some great texture in the shot also. Good composition.</td>', 'You''ve made a nice abstract here, IMO. Obviously nice lines, and some great texture in the shot also. Good composition.', '2005-06-09 02:48:05.000000', NULL, 1),
(1442916, 185256, 19831, '<td valign="top">Nice composition. Interesting capture. I like the dof you''ve used. Good job.</td>', 'Nice composition. Interesting capture. I like the dof you''ve used. Good job.', '2005-06-09 02:49:42.000000', NULL, 1),
(1442918, 186803, 19831, '<td valign="top">Very nice, interesting composition. Great detail and...TONS of texture going on :-)</td>', 'Very nice, interesting composition. Great detail and...TONS of texture going on :-)', '2005-06-09 02:51:33.000000', NULL, 1),
(1442922, 186532, 19831, '<td valign="top">Interesting concept. Fits the challenge nicely. I''m thinking maybe a tighter crop, filling the frame with the main subject, might improve the presentation of this shot. The pallet of pieces does have some interest, but IMO, the background just doesn''t seem to help.</td>', 'Interesting concept. Fits the challenge nicely. I''m thinking maybe a tighter crop, filling the frame with the main subject, might improve the presentation of this shot. The pallet of pieces does have some interest, but IMO, the background just doesn''t seem to help.', '2005-06-09 02:54:42.000000', NULL, 1),
(1442923, 186666, 28742, '<td valign="top">or: "The American Dream: An easily observable better value" ;-)</td>', 'or: "The American Dream: An easily observable better value" ;-)', '2005-06-09 02:56:03.000000', NULL, 1),
(1442925, 185409, 19831, '<td valign="top">This is a fitting subject and a good idea. The framing is putting me off just a little though. There seems to be an obvious ''tilt'' present in the photo. It''s hard to tell if the horizon in the distant background is actually level, but the structure itself, and especially the ledge in the foreground are tilted. This could be corrected with arbitrary rotation in ps. I''m also thinking that maybe if the ledge were actually cropped out, or maybe at least to the ledge itself, removing the ''rock wall'' portion in the bottom of the frame it could make the shot stronger, as to me, it seems to just be a distraction to your main subject.</td>', 'This is a fitting subject and a good idea. The framing is putting me off just a little though. There seems to be an obvious ''tilt'' present in the photo. It''s hard to tell if the horizon in the distant background is actually level, but the structure itself, and especially the ledge in the foreground are tilted. This could be corrected with arbitrary rotation in ps. I''m also thinking that maybe if the ledge were actually cropped out, or maybe at least to the ledge itself, removing the ''rock wall'' portion in the bottom of the frame it could make the shot stronger, as to me, it seems to just be a distraction to your main subject.', '2005-06-09 03:04:42.000000', NULL, 1),
(1442926, 186394, 28742, '<td valign="top">Seattle skyline. Great shot. Too bad it''s not brighter, but then that''s Seattle for ya. ;-) Good job on this!</td>', 'Seattle skyline. Great shot. Too bad it''s not brighter, but then that''s Seattle for ya. ;-) Good job on this!', '2005-06-09 03:04:53.000000', NULL, 1),
(1442929, 186200, 22914, '<td valign="top">Liked the toning.</td>', 'Liked the toning.', '2005-06-09 03:06:53.000000', NULL, 1),
(1442930, 186662, 19831, '<td valign="top">Maybe it''s just me, but I find my eye wandering, not really finding a strong focal point.</td>', 'Maybe it''s just me, but I find my eye wandering, not really finding a strong focal point.', '2005-06-09 03:10:15.000000', NULL, 1),
(1442937, 186444, 19831, '<td valign="top">Wowsers !!! What an awesome composition. First of all, great leading lines and use of vanishing points. The blue girders against the blue sky are very pleasing to my eye. And man, how long did you scope this place out to figure out the perfect timing for those shadows? They really make this shot. This is really a terrific photo, I could just sit and view it for awhile, in fact, I think I will :-) thanks.</td>', 'Wowsers !!! What an awesome composition. First of all, great leading lines and use of vanishing points. The blue girders against the blue sky are very pleasing to my eye. And man, how long did you scope this place out to figure out the perfect timing for those shadows? They really make this shot. This is really a terrific photo, I could just sit and view it for awhile, in fact, I think I will :-) thanks.', '2005-06-09 03:16:19.000000', NULL, 1),
(1442939, 185356, 19831, '<td valign="top">Very nice composition. Interesting and uncluttered. Good dof. By the looks of those burn marks on the wood though, maybe the blade needs to be sharpened? hehehe</td>', 'Very nice composition. Interesting and uncluttered. Good dof. By the looks of those burn marks on the wood though, maybe the blade needs to be sharpened? hehehe', '2005-06-09 03:19:00.000000', NULL, 1),
(1442940, 186955, 37250, '<td valign="top">Horizontal lines are askew and it throws off the balance of the picture...  Nice picture though<br/> <br/>Cheers, <br/> <br/>Eric R Thibodeau</td>', 'Horizontal lines are askew and it throws off the balance of the picture...  Nice picture though Cheers,  Eric R Thibodeau', '2005-06-09 03:19:59.000000', NULL, 1),
(1442941, 185645, 37250, '<td valign="top">Nice composition,  Like the colors...<br/> <br/>Cheers,<br/> <br/>Eric R Thibodeau</td>', 'Nice composition,  Like the colors... Cheers, Eric R Thibodeau', '2005-06-09 03:21:06.000000', NULL, 1),
(1442943, 186932, 37250, '<td valign="top">Very nice colors, I just wish that all ot the steering wheel was there.</td>', 'Very nice colors, I just wish that all ot the steering wheel was there.', '2005-06-09 03:22:26.000000', NULL, 1),
(1442944, 185657, 19831, '<td valign="top">Hmm, interesting subject. I see the connection to the challenge and it fits well IMO. It is a refreshing change from all the cranes and such. I don''t think the truck really helps the presentation though. I''m thinking that maybe a different perspective and losing the truck might make this a much stronger photo.</td>', 'Hmm, interesting subject. I see the connection to the challenge and it fits well IMO. It is a refreshing change from all the cranes and such. I don''t think the truck really helps the presentation though. I''m thinking that maybe a different perspective and losing the truck might make this a much stronger photo.', '2005-06-09 03:23:03.000000', NULL, 1),
(1442948, 185697, 19831, '<td valign="top">Simple, yet interesting composition. The angle you''ve used creates nice lines and angles with the window frames and roof edge. The tree in the right adds to the shot IMO. I''m wondering if perhaps at least the left window were not cut off at the top left corner, might be a tad bit stronger presentation?</td>', 'Simple, yet interesting composition. The angle you''ve used creates nice lines and angles with the window frames and roof edge. The tree in the right adds to the shot IMO. I''m wondering if perhaps at least the left window were not cut off at the top left corner, might be a tad bit stronger presentation?', '2005-06-09 03:27:57.000000', NULL, 1),
(1442952, 185657, 33249, '<td valign="top">the picture would stand alone (and look better) without the truck. Really wish it wasnt there</td>', 'the picture would stand alone (and look better) without the truck. Really wish it wasnt there', '2005-06-09 03:33:24.000000', NULL, 1),
(1442958, 184469, 19831, '<td valign="top">I find this a very interesting shot, but let me say why. I am very torn and undecided as to how much I like it or not, for a couple of reasons. For one thing, I''m not sure if it is how you''ve edited it in ps, or the lighting or what, but something about it gives me an ''odd'' feeling. Also the empty or ''negative'' space at right, I am a fan of the use of negative space and I feel it can be a very effective compostional tool, but is also easy to ''over do'' it, or not use it properly. At first glance it almost seems like too much here, but upon further examination, I find it balanced in an awkward yet poignant sort of way. I do like the overall composition and framing of the shot. I find it fresh and creative in this field of challenge entries. So anyways, though I am undecided about if I like or dislike, what I conclude is that the photo has compelled me to study and think about that, and that fact makes it a big success IMO, and I am therefore scoring it (not sure exactly where yet) towards the higher end of the voting scale. So in summary - Nice shot. :-)</td>', 'I find this a very interesting shot, but let me say why. I am very torn and undecided as to how much I like it or not, for a couple of reasons. For one thing, I''m not sure if it is how you''ve edited it in ps, or the lighting or what, but something about it gives me an ''odd'' feeling. Also the empty or ''negative'' space at right, I am a fan of the use of negative space and I feel it can be a very effective compostional tool, but is also easy to ''over do'' it, or not use it properly. At first glance it almost seems like too much here, but upon further examination, I find it balanced in an awkward yet poignant sort of way. I do like the overall composition and framing of the shot. I find it fresh and creative in this field of challenge entries. So anyways, though I am undecided about if I like or dislike, what I conclude is that the photo has compelled me to study and think about that, and that fact makes it a big success IMO, and I am therefore scoring it (not sure exactly where yet) towards the higher end of the voting scale. So in summary - Nice shot. :-)', '2005-06-09 03:44:30.000000', NULL, 1),
(1442959, 186857, 16241, '<td valign="top">great shot, i think it could have gone bigger?</td>', 'great shot, i think it could have gone bigger?', '2005-06-09 03:45:32.000000', NULL, 1),
(1442961, 185309, 19831, '<td valign="top">Simple, yet pleasing to the eye. Nice composition.</td>', 'Simple, yet pleasing to the eye. Nice composition.', '2005-06-09 03:47:06.000000', NULL, 1),
(1442963, 186950, 16241, '<td valign="top">good</td>', 'good', '2005-06-09 03:48:44.000000', NULL, 1),
(1442964, 185213, 19831, '<td valign="top">This is a very nice shot. I like your treatment of it in editing. I find it a very strong composition. It has great leading lines. The men in the center really add to the shot IMO. Great job.</td>', 'This is a very nice shot. I like your treatment of it in editing. I find it a very strong composition. It has great leading lines. The men in the center really add to the shot IMO. Great job.', '2005-06-09 03:51:35.000000', NULL, 1),
(1442966, 185129, 19831, '<td valign="top">This is a great idea. I like the curved path in the bottom of the photo. It seems kind of busy to me though, I find my eye wandering, looking for a strong focal point. Perhaps a different angle/perspective would make a stronger presentation?</td>', 'This is a great idea. I like the curved path in the bottom of the photo. It seems kind of busy to me though, I find my eye wandering, looking for a strong focal point. Perhaps a different angle/perspective would make a stronger presentation?', '2005-06-09 03:54:29.000000', NULL, 1),
(1442967, 186856, 19831, '<td valign="top">Nice composition. The shot has great lines and I like the play of light and shadow. The ladder really stands out well against the building background. Good eye.</td>', 'Nice composition. The shot has great lines and I like the play of light and shadow. The ladder really stands out well against the building background. Good eye.', '2005-06-09 03:58:18.000000', NULL, 1),
(1442968, 186716, 19831, '<td valign="top">Pretty composition. The road has a nice curve to it, I wonder how it would be if the frame were to the right just enough to include the far side of the curve? That is a nice simple, yet complimentary border you''ve used too.</td>', 'Pretty composition. The road has a nice curve to it, I wonder how it would be if the frame were to the right just enough to include the far side of the curve? That is a nice simple, yet complimentary border you''ve used too.', '2005-06-09 04:01:47.000000', NULL, 1),
(1442971, 185409, 19025, '<td valign="top">The wall at the bottom seems distracting..try straigtning out the picture a little to the left and crop the wall..</td>', 'The wall at the bottom seems distracting..try straigtning out the picture a little to the left and crop the wall..', '2005-06-09 04:05:46.000000', NULL, 1),
(1442972, 185849, 19025, '<td valign="top">do I see a ribbon for this one?  NICE shot!! 10 from me!!</td>', 'do I see a ribbon for this one?  NICE shot!! 10 from me!!', '2005-06-09 04:06:43.000000', NULL, 1),
(1442974, 184893, 19025, '<td valign="top">Why does this picture look like it''s been liquified?</td>', 'Why does this picture look like it''s been liquified?', '2005-06-09 04:08:42.000000', NULL, 1),
(1442978, 185448, 19831, '<td valign="top">People have created some great ''abstracts'' in this challenge, and this is one of them. Great lines, lots of texture, nice shapes and forms. The play of light and shadows really make the shot. Nice job.</td>', 'People have created some great ''abstracts'' in this challenge, and this is one of them. Great lines, lots of texture, nice shapes and forms. The play of light and shadows really make the shot. Nice job.', '2005-06-09 04:13:30.000000', NULL, 1),
(1442981, 184714, 19025, '<td valign="top">too small and blurry<br/></td>', 'too small and blurry', '2005-06-09 04:16:48.000000', NULL, 1),
(1442982, 185559, 19025, '<td valign="top">the clouds are distracting</td>', 'the clouds are distracting', '2005-06-09 04:17:11.000000', NULL, 1),
(1442983, 186880, 19831, '<td valign="top">Wow. Great composition. Very refreshingly creative for this challenge. Who''d have thought you could make ''construction'' sexy? hmm. Nice job.</td>', 'Wow. Great composition. Very refreshingly creative for this challenge. Who''d have thought you could make ''construction'' sexy? hmm. Nice job.', '2005-06-09 04:17:31.000000', NULL, 1),
(1442985, 186864, 19831, '<td valign="top">Very nice shot. Cool perspective. Great sky. I like your treatment of it. Good job.</td>', 'Very nice shot. Cool perspective. Great sky. I like your treatment of it. Good job.', '2005-06-09 04:20:45.000000', NULL, 1),
(1442991, 186830, 28875, '<td valign="top">Nice shot,looks out of focus though.</td>', 'Nice shot,looks out of focus though.', '2005-06-09 04:29:51.000000', NULL, 1),
(1442994, 185713, 28875, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2005-06-09 04:32:34.000000', NULL, 1),
(1442996, 184893, 28875, '<td valign="top">Interesting composition.</td>', 'Interesting composition.', '2005-06-09 04:36:32.000000', NULL, 1),
