(1443001, 186589, 36472, '<td valign="top">haha..great title. I do like the BW effect as well.</td>', 'haha..great title. I do like the BW effect as well.', '2005-06-09 04:43:11.000000', NULL, 1),
(1443004, 186915, 16241, '<td valign="top">nice capture of light, i like it</td>', 'nice capture of light, i like it', '2005-06-09 04:44:02.000000', NULL, 1),
