(1443387, 186159, 37410, '<td valign="top">funny shot and well executed</td>', 'funny shot and well executed', '2005-06-09 09:55:22.000000', NULL, 1),
(1443388, 185618, 27482, '<td valign="top">Cute shot, one for the family album and I´ll bet he´ll love this shot if he ever gets into some "real" construction work.  However, as an entry into a photography contest this doesn´t really hit the spot for me.  It´s framed a little bit tightly at the bottom, you almost cut off his toes and the bottom of the construtction work is cut off in several places.  Also image quality is lacking here, too much noise for my taste, especially in the water and sky.  I still gave this a 5 even despite the image quality because this shot makes me remember what it was like to be a kid.</td>', 'Cute shot, one for the family album and I´ll bet he´ll love this shot if he ever gets into some "real" construction work.  However, as an entry into a photography contest this doesn´t really hit the spot for me.  It´s framed a little bit tightly at the bottom, you almost cut off his toes and the bottom of the construtction work is cut off in several places.  Also image quality is lacking here, too much noise for my taste, especially in the water and sky.  I still gave this a 5 even despite the image quality because this shot makes me remember what it was like to be a kid.', '2005-06-09 09:55:43.000000', NULL, 1),
(1443389, 186625, 38925, '<td valign="top">very nice</td>', 'very nice', '2005-06-09 09:55:55.000000', NULL, 1),
