INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1444010, 186850, 38786, '<td valign="top">Good use of negative space.</td>', 'Good use of negative space.', '2005-06-09 15:40:20.000000', NULL, 1),
