(1445263, 186159, 7570, '<td valign="top">do u have their contact numbers?</td>', 'do u have their contact numbers?', '2005-06-10 02:43:49.000000', NULL, 1),
(1445315, 185159, 22914, '<td valign="top">Nice.</td>', 'Nice.', '2005-06-10 03:33:05.000000', NULL, 1),
(1445332, 184579, 29474, '<td valign="top">The buildings on the bottom right are a bit distracting. I would also have cropped away more of the sky.</td>', 'The buildings on the bottom right are a bit distracting. I would also have cropped away more of the sky.', '2005-06-10 04:04:37.000000', NULL, 1),
(1445346, 186692, 19831, '<td valign="top">This seems like a good subject. I like your b/w treatment. The rails provide good lines. In this case, the background seems to be not helping the presentation here IMO. I''m wondering if maybe framing the shot tighter and showing primarily and perhaps even more of the rails would make for a stronger photo?</td>', 'This seems like a good subject. I like your b/w treatment. The rails provide good lines. In this case, the background seems to be not helping the presentation here IMO. I''m wondering if maybe framing the shot tighter and showing primarily and perhaps even more of the rails would make for a stronger photo?', '2005-06-10 04:25:42.000000', NULL, 1),
(1445354, 184619, 29474, '<td valign="top">A little too dark to see the ''construction'' well.</td>', 'A little too dark to see the ''construction'' well.', '2005-06-10 04:32:13.000000', NULL, 1),
(1445358, 184867, 19831, '<td valign="top">Although I feel a narrow sizing such as this can make the right photo pleasing, In this case it doesn''t really appeal to me. Your focus seems like it could be sharper, it seems like a lot of detail is missing. It seems like with the narrow sizing, the main emphasis of the shot is the flags, but I find the big sign taking the attention away. Perhaps the sign is an integral part of the concept(as hinted too with the title), but with no detail I just can''t make out what it actually is or is saying, therefore it ends up being a distracting element to me. Maybe a different perspective/angle would make for a much stronger presentation of this idea?</td>', 'Although I feel a narrow sizing such as this can make the right photo pleasing, In this case it doesn''t really appeal to me. Your focus seems like it could be sharper, it seems like a lot of detail is missing. It seems like with the narrow sizing, the main emphasis of the shot is the flags, but I find the big sign taking the attention away. Perhaps the sign is an integral part of the concept(as hinted too with the title), but with no detail I just can''t make out what it actually is or is saying, therefore it ends up being a distracting element to me. Maybe a different perspective/angle would make for a much stronger presentation of this idea?', '2005-06-10 04:37:25.000000', NULL, 1),
(1445378, 186910, 29474, '<td valign="top">I hope that they don''t build like that.</td>', 'I hope that they don''t build like that.', '2005-06-10 05:03:49.000000', NULL, 1),
(1445452, 186574, 36487, '<td valign="top">Interesting Shot</td>', 'Interesting Shot', '2005-06-10 06:54:09.000000', NULL, 1),
(1445453, 186886, 30669, '<td valign="top">Looks like it is exhausted. Nice angle.</td>', 'Looks like it is exhausted. Nice angle.', '2005-06-10 06:54:26.000000', NULL, 1),
