(1447640, 186601, 31319, '<td valign="top">Interesting element of design.</td>', 'Interesting element of design.', '2005-06-11 14:25:36.000000', NULL, 1),
(1447642, 185687, 31319, '<td valign="top">What a unique view!  I wish you well with this outstanding submission.</td>', 'What a unique view!  I wish you well with this outstanding submission.', '2005-06-11 14:26:46.000000', NULL, 1),
(1447656, 186830, 31319, '<td valign="top">I really enjoy the interaction you got from your models and think the human element in this submission sets it apart and above many others in this particular challenge.  Regrettably, from a technical perspective, it seems oversharpened.</td>', 'I really enjoy the interaction you got from your models and think the human element in this submission sets it apart and above many others in this particular challenge.  Regrettably, from a technical perspective, it seems oversharpened.', '2005-06-11 14:34:55.000000', NULL, 1),
(1447660, 185657, 31319, '<td valign="top">Including the vehicle for scale was wise.  A very formidable structure,  this anthill.</td>', 'Including the vehicle for scale was wise.  A very formidable structure,  this anthill.', '2005-06-11 14:37:50.000000', NULL, 1),
(1447662, 186849, 31319, '<td valign="top">Good action shot - almost a journalistic feel to it.</td>', 'Good action shot - almost a journalistic feel to it.', '2005-06-11 14:38:48.000000', NULL, 1),
