(1447784, 185169, 35602, '<td valign="top">This was an awesome shot.  One of the best b&amp;w I''ve seen.  I give it a ten.  Wouldn''t change a thing.</td>', 'This was an awesome shot.  One of the best b&w I''ve seen.  I give it a ten.  Wouldn''t change a thing.', '2005-06-11 16:19:41.000000', NULL, 1),
(1447789, 185309, 35602, '<td valign="top">That would be a serious upset.  It looks like this house will get the view now, until one goes up in front of it.</td>', 'That would be a serious upset.  It looks like this house will get the view now, until one goes up in front of it.', '2005-06-11 16:30:34.000000', NULL, 1),
(1447791, 186918, 35602, '<td valign="top">Never realized how high you are on these things.  I saw this and I was immediately experiencing vertigo.  What a marvelous angle on this one.</td>', 'Never realized how high you are on these things.  I saw this and I was immediately experiencing vertigo.  What a marvelous angle on this one.', '2005-06-11 16:33:49.000000', NULL, 1),
(1447795, 186052, 35602, '<td valign="top">This was such a cute shot.  It wouldn''t have been so good unless the boy was in it, and the title is a real knee slapper.  Unique presentation of an otherwise mediocre shot.</td>', 'This was such a cute shot.  It wouldn''t have been so good unless the boy was in it, and the title is a real knee slapper.  Unique presentation of an otherwise mediocre shot.', '2005-06-11 16:36:25.000000', NULL, 1),
(1447797, 186910, 35602, '<td valign="top">I would have called this one drunken bricks and put a bottle of whiskey at the top.</td>', 'I would have called this one drunken bricks and put a bottle of whiskey at the top.', '2005-06-11 16:37:35.000000', NULL, 1),
(1447798, 185281, 35602, '<td valign="top">Very good use of positioning of your subject.  It takes up nearly the entire frame which adds a lot of perspective.</td>', 'Very good use of positioning of your subject.  It takes up nearly the entire frame which adds a lot of perspective.', '2005-06-11 16:39:16.000000', NULL, 1),
(1447803, 186746, 35602, '<td valign="top">Loved the repiition of shape on this one.  The light really exaggerates the idea of circles.  You did a wonderfully artistic piece here.</td>', 'Loved the repiition of shape on this one.  The light really exaggerates the idea of circles.  You did a wonderfully artistic piece here.', '2005-06-11 16:44:52.000000', NULL, 1),
(1447807, 186411, 34247, '<td valign="top">I think this image has potential, but the crop makes for a jarring composition. The horizontal tilt is severe, and has a severe impact on the eyes. The haziness of the image is also something that could be corrected. Two dots, one on each side of the crane, should be wiped off were this an advanced edit challenge. Overall a decent image, but again, the tilt is extremely problematic for me.</td>', 'I think this image has potential, but the crop makes for a jarring composition. The horizontal tilt is severe, and has a severe impact on the eyes. The haziness of the image is also something that could be corrected. Two dots, one on each side of the crane, should be wiped off were this an advanced edit challenge. Overall a decent image, but again, the tilt is extremely problematic for me.', '2005-06-11 16:55:40.000000', NULL, 1),
(1447808, 185559, 34247, '<td valign="top">SurREAListic processing. I like the effect, generally.</td>', 'SurREAListic processing. I like the effect, generally.', '2005-06-11 16:56:49.000000', NULL, 1),
(1447809, 186918, 34247, '<td valign="top">Interesting viewpoint and composition. I''m curious what this image would look like with the crane arm cropped out, and just the yellow pulley dominating the frame.</td>', 'Interesting viewpoint and composition. I''m curious what this image would look like with the crane arm cropped out, and just the yellow pulley dominating the frame.', '2005-06-11 16:58:23.000000', NULL, 1),
(1447812, 184893, 19978, '<td valign="top">A beautiful twist on the challenge. Wonderful all around. 8.</td>', 'A beautiful twist on the challenge. Wonderful all around. 8.', '2005-06-11 16:59:02.000000', NULL, 1),
(1447813, 186886, 34247, '<td valign="top">Dramatic image with a nice tilt.</td>', 'Dramatic image with a nice tilt.', '2005-06-11 16:59:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1447815, 185920, 34247, '<td valign="top">It''s a nice enough image, but I feel it lacks a definitive focal point. The silhouette approach works well, but my eyes are not settling on any distinct point, leaving me ambivalent about the image''s impact.</td>', 'It''s a nice enough image, but I feel it lacks a definitive focal point. The silhouette approach works well, but my eyes are not settling on any distinct point, leaving me ambivalent about the image''s impact.', '2005-06-11 17:00:41.000000', NULL, 1),
(1447816, 186013, 34247, '<td valign="top">The colors are washed out and I feel this could benefit from a contrast bump.</td>', 'The colors are washed out and I feel this could benefit from a contrast bump.', '2005-06-11 17:01:36.000000', NULL, 1),
(1447818, 186856, 34247, '<td valign="top">Nice yellow emphasis on a generally tonally subdued background. Great composition. 8</td>', 'Nice yellow emphasis on a generally tonally subdued background. Great composition. 8', '2005-06-11 17:02:41.000000', NULL, 1),
(1447819, 185697, 34247, '<td valign="top">The image to me lacks a focal point. I''m not sure what "the big deal" here is. Yeah, it''s wrapped up, but why is that interesting? Perhaps with more contrast and a different color scheme, this would make a better image.</td>', 'The image to me lacks a focal point. I''m not sure what "the big deal" here is. Yeah, it''s wrapped up, but why is that interesting? Perhaps with more contrast and a different color scheme, this would make a better image.', '2005-06-11 17:04:02.000000', NULL, 1),
(1447821, 186840, 34247, '<td valign="top">Like the repeating patterns here.</td>', 'Like the repeating patterns here.', '2005-06-11 17:04:26.000000', NULL, 1),
(1447823, 186547, 34247, '<td valign="top">DOF seems a bit too shallow here, and the nails are jarring to look at. Perhaps a stop down would have improved the focus for my eyes.</td>', 'DOF seems a bit too shallow here, and the nails are jarring to look at. Perhaps a stop down would have improved the focus for my eyes.', '2005-06-11 17:05:21.000000', NULL, 1),
(1447824, 186853, 34247, '<td valign="top">Image has potential I think, but it''s screaming for a closer crop to my eyes. As it is, there''s a lot of busy-ness, and I feel the impact of the rider, negotiating the obstacle course-like markers, is lost.</td>', 'Image has potential I think, but it''s screaming for a closer crop to my eyes. As it is, there''s a lot of busy-ness, and I feel the impact of the rider, negotiating the obstacle course-like markers, is lost.', '2005-06-11 17:06:35.000000', NULL, 1),
(1447829, 184886, 30817, '<td valign="top">Something surreal going on here.  I like it! One of my top ten for this week.</td>', 'Something surreal going on here.  I like it! One of my top ten for this week.', '2005-06-11 17:14:15.000000', NULL, 1),
(1447831, 186764, 19734, '<td valign="top">I really like the blue sky breaking through, really pops out. There is a lot of gray all around the picture though and it takes away from it for me. Maybe a panaramic like crop just along that big arm would have looked neat.</td>', 'I really like the blue sky breaking through, really pops out. There is a lot of gray all around the picture though and it takes away from it for me. Maybe a panaramic like crop just along that big arm would have looked neat.', '2005-06-11 17:15:11.000000', NULL, 1),
(1447833, 185696, 19734, '<td valign="top">Beautiful colors but too much open space for me. Good job though.</td>', 'Beautiful colors but too much open space for me. Good job though.', '2005-06-11 17:16:07.000000', NULL, 1),
(1447835, 186808, 19734, '<td valign="top">I like your fulfilment of the theme. Its a little dark though, seems like you could bring more detail out.</td>', 'I like your fulfilment of the theme. Its a little dark though, seems like you could bring more detail out.', '2005-06-11 17:17:08.000000', NULL, 1),
(1447837, 186445, 30817, '<td valign="top">Two shots of this scene in this week''s challenge. I like the way you composed this more than the other shot and I also appreciate that there are only two participants. I do feel that left border could come in to exclude the sky, however. One of my top ten scores of the week.</td>', 'Two shots of this scene in this week''s challenge. I like the way you composed this more than the other shot and I also appreciate that there are only two participants. I do feel that left border could come in to exclude the sky, however. One of my top ten scores of the week.', '2005-06-11 17:18:07.000000', NULL, 1),
(1447838, 186944, 19734, '<td valign="top">I really like this shot. It seems like its from the 20s and maybe sepia would have given it a better feel.</td>', 'I really like this shot. It seems like its from the 20s and maybe sepia would have given it a better feel.', '2005-06-11 17:18:54.000000', NULL, 1),
