(1450971, 184893, 35322, '<td valign="top">great photo, nice colors and contrast</td>', 'great photo, nice colors and contrast', '2005-06-13 06:58:03.000000', NULL, 1),
(1450973, 186417, 35322, '<td valign="top">nice picture</td>', 'nice picture', '2005-06-13 06:58:29.000000', NULL, 1),
(1450980, 186876, 35322, '<td valign="top">I think the sepia tone is great, I like the contrast. You captured that "tired" feeling at the end of a work day. Nice shot!</td>', 'I think the sepia tone is great, I like the contrast. You captured that "tired" feeling at the end of a work day. Nice shot!', '2005-06-13 07:00:26.000000', NULL, 1),
(1450982, 186200, 35322, '<td valign="top">Nice shot! I like the lightening. Sepia tone is great! I love it!</td>', 'Nice shot! I like the lightening. Sepia tone is great! I love it!', '2005-06-13 07:01:11.000000', NULL, 1),
(1450984, 186625, 35322, '<td valign="top">Wow, they look mean! I wouldn''t wanna get close to them. Nce shot!</td>', 'Wow, they look mean! I wouldn''t wanna get close to them. Nce shot!', '2005-06-13 07:01:50.000000', NULL, 1),
(1450986, 186843, 35322, '<td valign="top">I like the contrast. The soil texture is great!</td>', 'I like the contrast. The soil texture is great!', '2005-06-13 07:02:20.000000', NULL, 1),
