INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1450996, 186865, 35322, '<td valign="top">looks more like an "abandoned building" :-) Not on foucous and the light that comes from above is distracting</td>', 'looks more like an "abandoned building" :-) Not on foucous and the light that comes from above is distracting', '2005-06-13 07:08:01.000000', NULL, 1),
(1450998, 186139, 35322, '<td valign="top">oversharpened and not very clear</td>', 'oversharpened and not very clear', '2005-06-13 07:09:41.000000', NULL, 1),
(1451001, 185849, 35322, '<td valign="top">nice framing!</td>', 'nice framing!', '2005-06-13 07:11:18.000000', NULL, 1),
(1451055, 185618, 35548, '<td valign="top">Low light images are so hard to judge, normally I would say that the dark areas lack detail but with the light being that it is I think you may have squeezed out all the detail possible. Overall this is a nice image but I thing it would have been better if you didn''t place the boy and the wooden objects so that the are standing on the edge of the frame...To do this you would have had to stepped backwards a few steps so that you didn''t cut off the top of the object on the left.</td>', 'Low light images are so hard to judge, normally I would say that the dark areas lack detail but with the light being that it is I think you may have squeezed out all the detail possible. Overall this is a nice image but I thing it would have been better if you didn''t place the boy and the wooden objects so that the are standing on the edge of the frame...To do this you would have had to stepped backwards a few steps so that you didn''t cut off the top of the object on the left.', '2005-06-13 07:47:55.000000', NULL, 1),
(1451072, 186622, 35548, '<td valign="top">I think you missed the challenge description.  Nice image and would have been better if more of it were in focuse.  If you look, the center of the image is in perfect focus where the foreground and back ground needs some more focus...I suggest that you try to understand how to set your camera up to improve your "depth of field" in this situations... Not hard to do just requires a little understanding of light and how the settings on the camera work. In this case (brights light) you want to shoot with the smallest appreture possible.  You can do that with your choice of ISO speed or shutter speed.</td>', 'I think you missed the challenge description.  Nice image and would have been better if more of it were in focuse.  If you look, the center of the image is in perfect focus where the foreground and back ground needs some more focus...I suggest that you try to understand how to set your camera up to improve your "depth of field" in this situations... Not hard to do just requires a little understanding of light and how the settings on the camera work. In this case (brights light) you want to shoot with the smallest appreture possible.  You can do that with your choice of ISO speed or shutter speed.', '2005-06-13 07:54:22.000000', NULL, 1),
(1451076, 186406, 35548, '<td valign="top">Darl areas a bit dark, Fence is lost in the shadow.</td>', 'Darl areas a bit dark, Fence is lost in the shadow.', '2005-06-13 07:56:06.000000', NULL, 1),
(1451093, 185696, 15575, '<td valign="top">The lamp post is so distracting!  Definately worth going back and standing in front of it next time.  Also there seems to be a white band surounding the post (although that may just be my monitor) - did you use a lot of USM?  Without the post and USM it''d be a 7, but as it is a 5.</td>', 'The lamp post is so distracting!  Definately worth going back and standing in front of it next time.  Also there seems to be a white band surounding the post (although that may just be my monitor) - did you use a lot of USM?  Without the post and USM it''d be a 7, but as it is a 5.', '2005-06-13 08:02:33.000000', NULL, 1),
(1451102, 186169, 29474, '<td valign="top">Lovely photo. But stretching the link to the challenge theme.</td>', 'Lovely photo. But stretching the link to the challenge theme.', '2005-06-13 08:07:08.000000', NULL, 1),
(1451116, 185531, 35602, '<td valign="top">Nice depiction of motion.  I can still tell that it is a turning that is being constructed.  I also liked the use of available light.  Even with the motion, there is still detail detected.</td>', 'Nice depiction of motion.  I can still tell that it is a turning that is being constructed.  I also liked the use of available light.  Even with the motion, there is still detail detected.', '2005-06-13 08:12:47.000000', NULL, 1),
(1451123, 186804, 35602, '<td valign="top">Nice b&amp;W but the foreground could have used less light.  I think a higher contrast setting on either your camera or in your editing program would have improved it.  Also try normal focus on your camera, then hard focus and see which one you like best.  A tripod should also be used if you haven''t got one.</td>', 'Nice b&W but the foreground could have used less light.  I think a higher contrast setting on either your camera or in your editing program would have improved it.  Also try normal focus on your camera, then hard focus and see which one you like best.  A tripod should also be used if you haven''t got one.', '2005-06-13 08:17:32.000000', NULL, 1),
(1451137, 184896, 35602, '<td valign="top">I have a real soft spot for b&amp;w.  I originally went with a nine, but when I reviewed my votes, I decided a seven was better.  It seemed too dark and the rocks in the foreground needed to be sharper.  Use manual focus and mid aperture setting (if you have it) and focus on the top of the furthest back rock and the entire image may have been well focused.</td>', 'I have a real soft spot for b&w.  I originally went with a nine, but when I reviewed my votes, I decided a seven was better.  It seemed too dark and the rocks in the foreground needed to be sharper.  Use manual focus and mid aperture setting (if you have it) and focus on the top of the furthest back rock and the entire image may have been well focused.', '2005-06-13 08:21:49.000000', NULL, 1),
(1451142, 185205, 35602, '<td valign="top">Extremely good composition.  A little more brightness on the man, and I would have given it a ten.  So I gave it a nine.</td>', 'Extremely good composition.  A little more brightness on the man, and I would have given it a ten.  So I gave it a nine.', '2005-06-13 08:23:33.000000', NULL, 1),
(1451153, 186445, 35602, '<td valign="top">This was one of those shots that you had to be in the right place at the right time.  The convex reflection really makes the shot.  It would have been mediocre if that wasn''t there.  Didn''t give it a ten because there was a degradation in the clarity, but I gave it a nine.</td>', 'This was one of those shots that you had to be in the right place at the right time.  The convex reflection really makes the shot.  It would have been mediocre if that wasn''t there.  Didn''t give it a ten because there was a degradation in the clarity, but I gave it a nine.', '2005-06-13 08:25:54.000000', NULL, 1),
(1451154, 186884, 29474, '<td valign="top">I think that more of the building and less of the sky would have made this a better picture. Maybe even a slightly different angle?</td>', 'I think that more of the building and less of the sky would have made this a better picture. Maybe even a slightly different angle?', '2005-06-13 08:26:14.000000', NULL, 1),
(1451161, 185443, 35602, '<td valign="top">A lot of noise in the sky.  Perhaps it is the size of the file.  However, your capture of the falling debris was perfect.</td>', 'A lot of noise in the sky.  Perhaps it is the size of the file.  However, your capture of the falling debris was perfect.', '2005-06-13 08:27:51.000000', NULL, 1),
(1451168, 185100, 35602, '<td valign="top">I like the starry look of the streetlights.  Your detail in the background,with the light stabbing through the dark, was really good.  However, the foreground is very unclear.  Try prefocusing on a mid point in the image and change the amount of light coming in several times to see which image looks the best.  Also, use a tripod if you didn''t.</td>', 'I like the starry look of the streetlights.  Your detail in the background,with the light stabbing through the dark, was really good.  However, the foreground is very unclear.  Try prefocusing on a mid point in the image and change the amount of light coming in several times to see which image looks the best.  Also, use a tripod if you didn''t.', '2005-06-13 08:30:15.000000', NULL, 1),
(1451175, 186940, 35602, '<td valign="top">A little dark.  On this one, a little fill in flash (place a handkerchief or some other transparent fabric over it to decrease overexposure) would have improved the image of the man a lot.</td>', 'A little dark.  On this one, a little fill in flash (place a handkerchief or some other transparent fabric over it to decrease overexposure) would have improved the image of the man a lot.', '2005-06-13 08:33:38.000000', NULL, 1),
(1451186, 186722, 35602, '<td valign="top">I like the way you filled the frame on this one.  Even the fiber on the rope is visible.  What iso setting did you use?  I think a shot in all available ones, then choosing the least noisy one would have improved it.  Also when you take several shots of the same subject, use a tripod so you don''t change the composition you''ve chosen.</td>', 'I like the way you filled the frame on this one.  Even the fiber on the rope is visible.  What iso setting did you use?  I think a shot in all available ones, then choosing the least noisy one would have improved it.  Also when you take several shots of the same subject, use a tripod so you don''t change the composition you''ve chosen.', '2005-06-13 08:36:36.000000', NULL, 1),
(1451192, 184714, 35602, '<td valign="top">Sorry.  Image is too small and very digital looking which makes it really out of focus.</td>', 'Sorry.  Image is too small and very digital looking which makes it really out of focus.', '2005-06-13 08:38:01.000000', NULL, 1),
(1451197, 184585, 35602, '<td valign="top">Didn''t like the yellow ribbon crossing the photo.  If it said caution, you should have depicted that in the picture.  As it is, it is very distracting.</td>', 'Didn''t like the yellow ribbon crossing the photo.  If it said caution, you should have depicted that in the picture.  As it is, it is very distracting.', '2005-06-13 08:39:09.000000', NULL, 1),
(1451203, 185279, 35602, '<td valign="top">A sign, construction does not make.  Also the car is way out of focus.  Sure it was moving, but most cameras can capture a clearer image of motion if you set it right.  Prefocus on the point you want to take the picture, then snap it when the image reaches that point.</td>', 'A sign, construction does not make.  Also the car is way out of focus.  Sure it was moving, but most cameras can capture a clearer image of motion if you set it right.  Prefocus on the point you want to take the picture, then snap it when the image reaches that point.', '2005-06-13 08:40:58.000000', NULL, 1),
(1451207, 185513, 35602, '<td valign="top">Not sure what this is, other than fire.</td>', 'Not sure what this is, other than fire.', '2005-06-13 08:41:46.000000', NULL, 1),
(1451214, 186935, 35602, '<td valign="top">Too much glare on the light spots.  Use a tripod and reduce the amount of light coming in to the camera.  Also try changing contrast to a clower setting and white balance from auto to another setting on your camera.</td>', 'Too much glare on the light spots.  Use a tripod and reduce the amount of light coming in to the camera.  Also try changing contrast to a clower setting and white balance from auto to another setting on your camera.', '2005-06-13 08:43:24.000000', NULL, 1),
(1451224, 185752, 29474, '<td valign="top">I like this picture, but my interpretation of the theme is that there should still be some evidence of ''construction''. Not a completed building.</td>', 'I like this picture, but my interpretation of the theme is that there should still be some evidence of ''construction''. Not a completed building.', '2005-06-13 08:46:40.000000', NULL, 1),
(1451249, 185674, 29474, '<td valign="top">The lampost detracts from the picture. Pity it could not be cloned out. Otherwise the cranes are nicely in balance.</td>', 'The lampost detracts from the picture. Pity it could not be cloned out. Otherwise the cranes are nicely in balance.', '2005-06-13 08:57:04.000000', NULL, 1),
(1451291, 184707, 29474, '<td valign="top">No matter how much I stretch my imagination I still cannot fit this into the challenge.</td>', 'No matter how much I stretch my imagination I still cannot fit this into the challenge.', '2005-06-13 09:16:02.000000', NULL, 1),
(1451301, 186168, 29474, '<td valign="top">Another nice photograph, but, by my interpretation, outside the challenge theme.</td>', 'Another nice photograph, but, by my interpretation, outside the challenge theme.', '2005-06-13 09:21:22.000000', NULL, 1),
(1451310, 185891, 35322, '<td valign="top">the light in the middle is very distracting, you can''t see all the cranes lining up. toobad.</td>', 'the light in the middle is very distracting, you can''t see all the cranes lining up. toobad.', '2005-06-13 09:29:18.000000', NULL, 1),
(1451313, 186817, 35322, '<td valign="top">the shadow covers up everything, you can''t tell what''s in.</td>', 'the shadow covers up everything, you can''t tell what''s in.', '2005-06-13 09:30:22.000000', NULL, 1),
(1451316, 186883, 35322, '<td valign="top">too bright, and no contrast</td>', 'too bright, and no contrast', '2005-06-13 09:31:02.000000', NULL, 1),
(1451317, 185987, 35322, '<td valign="top">very nice. I like the sepia tone and the orange on the guy, they match perfectly.</td>', 'very nice. I like the sepia tone and the orange on the guy, they match perfectly.', '2005-06-13 09:32:02.000000', NULL, 1),
(1451320, 186159, 35322, '<td valign="top">nice capture, but not very clear., you should have more contrast also</td>', 'nice capture, but not very clear., you should have more contrast also', '2005-06-13 09:32:58.000000', NULL, 1),
(1451326, 185485, 35322, '<td valign="top">too many things in one image  and nothing is realy on focus...disturbing.</td>', 'too many things in one image  and nothing is realy on focus...disturbing.', '2005-06-13 09:35:01.000000', NULL, 1),
(1451329, 185656, 35322, '<td valign="top">the image is not very clear, the edges are blured</td>', 'the image is not very clear, the edges are blured', '2005-06-13 09:37:44.000000', NULL, 1),
(1451334, 185956, 35322, '<td valign="top">the object that crosses the image on the diagonal si very disturbing. too much sky also</td>', 'the object that crosses the image on the diagonal si very disturbing. too much sky also', '2005-06-13 09:40:18.000000', NULL, 1),
(1451338, 185038, 35322, '<td valign="top">nice picture, although ther edges of the tool bag seem to bee "violet"</td>', 'nice picture, although ther edges of the tool bag seem to bee "violet"', '2005-06-13 09:42:26.000000', NULL, 1),
(1451340, 186870, 35322, '<td valign="top">nice contrast. I just love the picture</td>', 'nice contrast. I just love the picture', '2005-06-13 09:43:02.000000', NULL, 1),
(1451343, 185213, 35322, '<td valign="top">very nice. I just love the sepia tone.. Th contrast seems a little too much.</td>', 'very nice. I just love the sepia tone.. Th contrast seems a little too much.', '2005-06-13 09:44:12.000000', NULL, 1),
(1451344, 186445, 35322, '<td valign="top">Nice capture. I love the reflection in the bean!</td>', 'Nice capture. I love the reflection in the bean!', '2005-06-13 09:44:45.000000', NULL, 1),
(1451347, 184969, 35322, '<td valign="top">very nice picture. You managed to capture the depressing fealing of living in a "box of matches"..the big cities are like his.</td>', 'very nice picture. You managed to capture the depressing fealing of living in a "box of matches"..the big cities are like his.', '2005-06-13 09:45:51.000000', NULL, 1),
(1451349, 185554, 35322, '<td valign="top">nice capture. the wire in the topside is a little bit distracting, but I suppose is not easy to take a good shot and not to have this .</td>', 'nice capture. the wire in the topside is a little bit distracting, but I suppose is not easy to take a good shot and not to have this .', '2005-06-13 09:47:37.000000', NULL, 1),
(1451351, 185687, 35322, '<td valign="top">wow, nice view. I''d love to get upthere sometimes.</td>', 'wow, nice view. I''d love to get upthere sometimes.', '2005-06-13 09:48:08.000000', NULL, 1),
(1451356, 186744, 35322, '<td valign="top">better "if I had a nail". nice picture anyway! I love the blue touch!</td>', 'better "if I had a nail". nice picture anyway! I love the blue touch!', '2005-06-13 09:48:50.000000', NULL, 1),
(1451357, 186169, 35322, '<td valign="top">nice picture, but where is the construction?</td>', 'nice picture, but where is the construction?', '2005-06-13 09:49:19.000000', NULL, 1),
(1451361, 186876, 27482, '<td valign="top">Awesome shot, love everything about it, especially the feel to it and the tonal range and there is nothing more I can say except I gave it a 10 and added it to my favorites.  Great job as far as I am concerned.</td>', 'Awesome shot, love everything about it, especially the feel to it and the tonal range and there is nothing more I can say except I gave it a 10 and added it to my favorites.  Great job as far as I am concerned.', '2005-06-13 09:51:50.000000', NULL, 1),
(1451371, 186878, 27482, '<td valign="top">Sorry but the whole upside down feeling here doesn´t appeal to me at all, other than that not bad at all.</td>', 'Sorry but the whole upside down feeling here doesn´t appeal to me at all, other than that not bad at all.', '2005-06-13 09:59:06.000000', NULL, 1),
(1451377, 184931, 27482, '<td valign="top">Nice and simple, I like it but not heaps, gave it a 6.</td>', 'Nice and simple, I like it but not heaps, gave it a 6.', '2005-06-13 10:04:02.000000', NULL, 1),
(1451381, 186411, 36487, '<td valign="top">Would have been better with more bridge</td>', 'Would have been better with more bridge', '2005-06-13 10:06:53.000000', NULL, 1),
(1451421, 186490, 37334, '<td valign="top">I like this image, the thing that spoils it is the washed out colours and the blown highlights? Like the idea though.</td>', 'I like this image, the thing that spoils it is the washed out colours and the blown highlights? Like the idea though.', '2005-06-13 10:16:33.000000', NULL, 1),
(1451430, 186864, 37334, '<td valign="top">Lovely b&amp;w...gives me vertigo;) 8</td>', 'Lovely b&w...gives me vertigo;) 8', '2005-06-13 10:19:25.000000', NULL, 1),
(1451431, 185687, 26679, '<td valign="top">This is a fantastic images which for me has not reached its full potential. I have taken the liberty of reproducing it in sepia and it is sitting in my portfolio at the moment.<br/></td>', 'This is a fantastic images which for me has not reached its full potential. I have taken the liberty of reproducing it in sepia and it is sitting in my portfolio at the moment.', '2005-06-13 10:19:28.000000', NULL, 1),
(1451443, 186860, 37334, '<td valign="top">I like the graffiti and the colours</td>', 'I like the graffiti and the colours', '2005-06-13 10:22:07.000000', NULL, 1),
(1451449, 186951, 37334, '<td valign="top">Love the light and colours on the nails..the background is interesting too - holds my interest 8</td>', 'Love the light and colours on the nails..the background is interesting too - holds my interest 8', '2005-06-13 10:23:31.000000', NULL, 1),
(1451454, 186574, 37334, '<td valign="top">Brilliant! 10</td>', 'Brilliant! 10', '2005-06-13 10:25:34.000000', NULL, 1),
(1451460, 186200, 37334, '<td valign="top">Construction? Going to break my own rule 9:)</td>', 'Construction? Going to break my own rule 9:)', '2005-06-13 10:26:59.000000', NULL, 1),
(1451461, 184942, 27482, '<td valign="top">Not a bad idea but it´s really uninteresting as it is, this photo desperatly needs a great sunset or sky for it to work but I like the panorama composition.  Also it seems to me a bit oversaturated and needs some more sharpness.</td>', 'Not a bad idea but it´s really uninteresting as it is, this photo desperatly needs a great sunset or sky for it to work but I like the panorama composition.  Also it seems to me a bit oversaturated and needs some more sharpness.', '2005-06-13 10:27:04.000000', NULL, 1),
(1451474, 186622, 29474, '<td valign="top">Can''t / Don''t want to see the link to the challenge theme.</td>', 'Can''t / Don''t want to see the link to the challenge theme.', '2005-06-13 10:29:16.000000', NULL, 1),
(1451482, 186830, 27482, '<td valign="top">I don´t know what filter or effect you used to get that contrasty gloss effect but it´s not really working for me at all, sorry.  Other than that it looks like a nice shot, I would have tried to get all of them in the shot though, the guy on the far left has a steel bar over his face.</td>', 'I don´t know what filter or effect you used to get that contrasty gloss effect but it´s not really working for me at all, sorry.  Other than that it looks like a nice shot, I would have tried to get all of them in the shot though, the guy on the far left has a steel bar over his face.', '2005-06-13 10:32:27.000000', NULL, 1),
(1451485, 186830, 37334, '<td valign="top">Happy workers! 7</td>', 'Happy workers! 7', '2005-06-13 10:33:26.000000', NULL, 1),
(1451492, 186546, 37334, '<td valign="top">I really like this -good composition!10</td>', 'I really like this -good composition!10', '2005-06-13 10:36:34.000000', NULL, 1),
(1451494, 186944, 7689, '<td valign="top">Nice DOF and nice angle.. this is a good shot showing construction in progress. Image clarity is a little poor due to low light.</td>', 'Nice DOF and nice angle.. this is a good shot showing construction in progress. Image clarity is a little poor due to low light.', '2005-06-13 10:36:49.000000', NULL, 1),
(1451498, 186604, 37334, '<td valign="top">Really interesting composition 9</td>', 'Really interesting composition 9', '2005-06-13 10:38:02.000000', NULL, 1),
