(1453378, 186585, 35602, '<td valign="top">Is this like Where''s Waldo?  Anyway, this looks like an image that could look nearly haunted if it was taken at night, but I''m not sure if there is any light on it.  As it stands, it looks pretty spooky.  It definitely meets the challenge but the image itself seems broken up or something.  Can''t quite put my finger on it.</td>', 'Is this like Where''s Waldo?  Anyway, this looks like an image that could look nearly haunted if it was taken at night, but I''m not sure if there is any light on it.  As it stands, it looks pretty spooky.  It definitely meets the challenge but the image itself seems broken up or something.  Can''t quite put my finger on it.', '2005-06-13 22:31:02.000000', NULL, 1),
(1453382, 186200, 4793, '<td valign="top">Beautiful tones, overall nice shot.</td>', 'Beautiful tones, overall nice shot.', '2005-06-13 22:31:59.000000', NULL, 1),
(1453384, 186840, 35602, '<td valign="top">Just didn''t like the busyness of all the beams.  I know that they take up a lot of area and you couldn''t have taken much out of it.  Maybe more of a closeup on one area?  Don''t really know.</td>', 'Just didn''t like the busyness of all the beams.  I know that they take up a lot of area and you couldn''t have taken much out of it.  Maybe more of a closeup on one area?  Don''t really know.', '2005-06-13 22:32:45.000000', NULL, 1),
(1453389, 185630, 4793, '<td valign="top">Interesting shot, nice composition</td>', 'Interesting shot, nice composition', '2005-06-13 22:34:16.000000', NULL, 1),
(1453436, 186907, 36914, '<td valign="top">Persepective is a little tilted.</td>', 'Persepective is a little tilted.', '2005-06-13 22:52:20.000000', NULL, 1),
(1453440, 186803, 36914, '<td valign="top">Real good Depth of Field, nice crisp focus.</td>', 'Real good Depth of Field, nice crisp focus.', '2005-06-13 22:56:33.000000', NULL, 1),
(1453474, 185583, 38606, '<td valign="top">It is a really good concept, but I think that the picture would be better if the pipe that you were looking through was completely circular.</td>', 'It is a really good concept, but I think that the picture would be better if the pipe that you were looking through was completely circular.', '2005-06-13 23:10:04.000000', NULL, 1),
(1453491, 186807, 35530, '<td valign="top">Got to give you credit on this one. You took a mundane object and turned it into a very nice abstract. Nice effort. 8</td>', 'Got to give you credit on this one. You took a mundane object and turned it into a very nice abstract. Nice effort. 8', '2005-06-13 23:27:33.000000', NULL, 1),
(1453494, 185891, 35530, '<td valign="top">Very nice capture. I would have liked this a lot more if it was taken at a different time of day so the sun flare wasn''t there.</td>', 'Very nice capture. I would have liked this a lot more if it was taken at a different time of day so the sun flare wasn''t there.', '2005-06-13 23:29:03.000000', NULL, 1),
(1453500, 186910, 35530, '<td valign="top">Nobody sneeze.</td>', 'Nobody sneeze.', '2005-06-13 23:34:55.000000', NULL, 1),
(1453503, 186038, 35530, '<td valign="top">So that''s where they come from.</td>', 'So that''s where they come from.', '2005-06-13 23:37:52.000000', NULL, 1),
(1453505, 185443, 35530, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2005-06-13 23:38:39.000000', NULL, 1),
(1453516, 186765, 35530, '<td valign="top">Very good image. Good luck.</td>', 'Very good image. Good luck.', '2005-06-13 23:43:38.000000', NULL, 1),
(1453519, 185920, 35530, '<td valign="top">Nice colors</td>', 'Nice colors', '2005-06-13 23:44:23.000000', NULL, 1),
(1453671, 185038, 38476, '<td valign="top">Well spotted! Good idea for a subject.</td>', 'Well spotted! Good idea for a subject.', '2005-06-14 00:32:48.000000', NULL, 1),
(1453688, 186513, 38476, '<td valign="top">Good idea, but I was very distracted by the shadows &amp; the reddish reflection...</td>', 'Good idea, but I was very distracted by the shadows & the reddish reflection...', '2005-06-14 00:40:14.000000', NULL, 1),
(1453698, 186861, 32240, '<td valign="top">Nice shot...like all the angles</td>', 'Nice shot...like all the angles', '2005-06-14 00:43:18.000000', NULL, 1),
(1453776, 185283, 9363, '<td valign="top">silly :)</td>', 'silly :)', '2005-06-14 01:24:33.000000', NULL, 1),
(1453821, 186604, 39231, '<td valign="top">i would have taken out the pipes and focussed more on the machine, that way it would tell more of the story of what the picture is about. It wouldn''t be so hard to figure out what the subject or concept is.</td>', 'i would have taken out the pipes and focussed more on the machine, that way it would tell more of the story of what the picture is about. It wouldn''t be so hard to figure out what the subject or concept is.', '2005-06-14 01:45:02.000000', NULL, 1),
(1453836, 184610, 39231, '<td valign="top">the spider is a bit overexposed, but a good concept!!!</td>', 'the spider is a bit overexposed, but a good concept!!!', '2005-06-14 01:51:17.000000', NULL, 1),
(1453858, 186550, 39231, '<td valign="top">interesting concept. i like it. needs a little more focussing on the nails.</td>', 'interesting concept. i like it. needs a little more focussing on the nails.', '2005-06-14 02:02:01.000000', NULL, 1),
(1453865, 186692, 39231, '<td valign="top">good concept, maybe crop it a little at the top to focus more on the railway lines, thus enhancing your theme.</td>', 'good concept, maybe crop it a little at the top to focus more on the railway lines, thus enhancing your theme.', '2005-06-14 02:10:14.000000', NULL, 1),
(1453904, 186875, 38508, '<td valign="top">A simple idea.. but a very nice image!  (8)</td>', 'A simple idea.. but a very nice image!  (8)', '2005-06-14 03:02:18.000000', NULL, 1),
(1453914, 186744, 32157, '<td valign="top">love the gritty colors in this one. almost seems as if i''m there.</td>', 'love the gritty colors in this one. almost seems as if i''m there.', '2005-06-14 03:19:11.000000', NULL, 1),
(1453926, 185752, 32157, '<td valign="top">is this a place in iceland?</td>', 'is this a place in iceland?', '2005-06-14 03:24:28.000000', NULL, 1),
(1453928, 186546, 32157, '<td valign="top">a lil dark. but it does add a lil bit of atmosphere, albeit a gloomy one, hehe</td>', 'a lil dark. but it does add a lil bit of atmosphere, albeit a gloomy one, hehe', '2005-06-14 03:25:16.000000', NULL, 1),
(1453932, 186015, 32157, '<td valign="top">very beautiful. i love the way you made the sky such a huge contrast in this one.</td>', 'very beautiful. i love the way you made the sky such a huge contrast in this one.', '2005-06-14 03:27:07.000000', NULL, 1),
(1453967, 185169, 39073, '<td valign="top">I like it..  It''s dark and obscure and has also a nice compositon.</td>', 'I like it..  It''s dark and obscure and has also a nice compositon.', '2005-06-14 03:58:06.000000', NULL, 1),
(1453980, 186807, 35970, '<td valign="top">I think it is very artistic and I love the texture, but I am afraid this will not win. The warm colors offset the metallic nature. This photographer has made art out of the ordinary. Perhaps the only thing missing is the excitement of movement, but I don''t know how that would be possibly captured, given the subject matter.</td>', 'I think it is very artistic and I love the texture, but I am afraid this will not win. The warm colors offset the metallic nature. This photographer has made art out of the ordinary. Perhaps the only thing missing is the excitement of movement, but I don''t know how that would be possibly captured, given the subject matter.', '2005-06-14 04:09:45.000000', NULL, 1),
(1453987, 186589, 35322, '<td valign="top">nice shot</td>', 'nice shot', '2005-06-14 04:21:49.000000', NULL, 1),
(1453989, 186448, 35322, '<td valign="top">The light is too strong, whixh makes the contrast high and  the picture not very clear. Also the trees and the wall in front are distracting.</td>', 'The light is too strong, whixh makes the contrast high and  the picture not very clear. Also the trees and the wall in front are distracting.', '2005-06-14 04:26:03.000000', NULL, 1),
(1453992, 186880, 35970, '<td valign="top">this composition seems well balanced in forms and shapes, colors and tones. The colors work really well together. The shape of the female hand works with the composition, but adds some question of what it means.</td>', 'this composition seems well balanced in forms and shapes, colors and tones. The colors work really well together. The shape of the female hand works with the composition, but adds some question of what it means.', '2005-06-14 04:36:23.000000', NULL, 1),
(1454004, 185431, 19831, '<td valign="top">An interesting idea. Could be a good subject. It seems out of focus though. This presentation seems kind of lacking. It looks like you just saw this stuff and stood there and took a quick snapshot of it. Perhaps a different perspective/angle would make for a stronger photo?</td>', 'An interesting idea. Could be a good subject. It seems out of focus though. This presentation seems kind of lacking. It looks like you just saw this stuff and stood there and took a quick snapshot of it. Perhaps a different perspective/angle would make for a stronger photo?', '2005-06-14 04:58:17.000000', NULL, 1),
(1454006, 186918, 19831, '<td valign="top">Wowsers. Havn''t seen quite this same perspective in the challenge. Obviously, the height here is what makes this shot kind of cool. Heck, I''d be petrified beyond all comprehension up there , kind of scary even looking at this pic :-P , so extra points just for having the nerve to go up there.</td>', 'Wowsers. Havn''t seen quite this same perspective in the challenge. Obviously, the height here is what makes this shot kind of cool. Heck, I''d be petrified beyond all comprehension up there , kind of scary even looking at this pic :-P , so extra points just for having the nerve to go up there.', '2005-06-14 05:03:44.000000', NULL, 1),
(1454013, 186666, 19831, '<td valign="top">You''ve tied this in to make the shot work well for this challenge IMO. The sign, the house nearly finished in the background and even the truck out front conveys a story to the viewer nicely. One thing that is kind of distracting to my eye is the sky over top of the sign jutting out. I''m wondering if maybe cropping down to the top of the sign would make for a little stronger presentation?</td>', 'You''ve tied this in to make the shot work well for this challenge IMO. The sign, the house nearly finished in the background and even the truck out front conveys a story to the viewer nicely. One thing that is kind of distracting to my eye is the sky over top of the sign jutting out. I''m wondering if maybe cropping down to the top of the sign would make for a little stronger presentation?', '2005-06-14 05:12:06.000000', NULL, 1),
(1454019, 184848, 19831, '<td valign="top">This could be a good idea? But I find the composition to be weak and lacking any cohesion of the elements as presented. This perspective is not moving at all, it would appear that you just stood there and took a quick snapshot at the ground. The bones maybe have some interest, but the squashed food is not very appealing. And overall, try as I might, I can''t really see any connection at all to the ''Construction'' theme of this challenge.</td>', 'This could be a good idea? But I find the composition to be weak and lacking any cohesion of the elements as presented. This perspective is not moving at all, it would appear that you just stood there and took a quick snapshot at the ground. The bones maybe have some interest, but the squashed food is not very appealing. And overall, try as I might, I can''t really see any connection at all to the ''Construction'' theme of this challenge.', '2005-06-14 05:19:29.000000', NULL, 1),
(1454023, 186836, 19831, '<td valign="top">This could be a good idea/subject. There are interesting colors and shapes in the various houses. I think possibly a different perspective/angle might make for a stronger photo. This shot seems a little weak compositionally, and that tree right smack in the middle of everything, especially with the top cut off, just seems to be a big distracting element.</td>', 'This could be a good idea/subject. There are interesting colors and shapes in the various houses. I think possibly a different perspective/angle might make for a stronger photo. This shot seems a little weak compositionally, and that tree right smack in the middle of everything, especially with the top cut off, just seems to be a big distracting element.', '2005-06-14 05:24:48.000000', NULL, 1),
(1454031, 184581, 19831, '<td valign="top">Nice photo. Great focus and lighting. Excellant detail and some awesome texture going on. Good job.</td>', 'Nice photo. Great focus and lighting. Excellant detail and some awesome texture going on. Good job.', '2005-06-14 05:30:25.000000', NULL, 1),
(1454032, 186200, 19831, '<td valign="top">Very cool shot. This is a great perspective. Awesome use of leading lines and vanishing point. I really like your treatment of it, hope you have photogs comments on it so I can check it out after the challenge. Hope this does well, I really like it. Nice job.</td>', 'Very cool shot. This is a great perspective. Awesome use of leading lines and vanishing point. I really like your treatment of it, hope you have photogs comments on it so I can check it out after the challenge. Hope this does well, I really like it. Nice job.', '2005-06-14 05:31:51.000000', NULL, 1),
(1454033, 186823, 37334, '<td valign="top">I like this. It''s moody. I like the contrast and different textures. 8</td>', 'I like this. It''s moody. I like the contrast and different textures. 8', '2005-06-14 05:32:10.000000', NULL, 1),
(1454036, 185038, 37334, '<td valign="top">Like it..it''s really interesting, nice subdued colours and enough  detail to hold your attention 9</td>', 'Like it..it''s really interesting, nice subdued colours and enough  detail to hold your attention 9', '2005-06-14 05:37:21.000000', NULL, 1),
(1454038, 185990, 37334, '<td valign="top">Really nice graphic image. Nice play between the blues and yellows. I would have loved a bit more depth of field;)</td>', 'Really nice graphic image. Nice play between the blues and yellows. I would have loved a bit more depth of field;)', '2005-06-14 05:38:58.000000', NULL, 1),
(1454041, 186577, 37334, '<td valign="top">I really want to know what''s going on here - Has the car crashed? Stalled? Is this pub in NI, do they serve guinness..so many questions:)</td>', 'I really want to know what''s going on here - Has the car crashed? Stalled? Is this pub in NI, do they serve guinness..so many questions:)', '2005-06-14 05:40:57.000000', NULL, 1),
(1454043, 186722, 37334, '<td valign="top">I want to cry...I want to cry buckets and then leave DPC...where''s my valium?<br/>I want to say this is a really bad image..I want to give you a 1 and sleep soundly tonight..but I can''t...I hate you...A lovely crisp B &amp;W...with detail and texture and did I mention I hated you? I love the peeling paint ( and hate you)..it''s graphic, it''s beautiful reminds me of Lewis Hine''s work and I HATE you 10:))</td>', 'I want to cry...I want to cry buckets and then leave DPC...where''s my valium?I want to say this is a really bad image..I want to give you a 1 and sleep soundly tonight..but I can''t...I hate you...A lovely crisp B &W...with detail and texture and did I mention I hated you? I love the peeling paint ( and hate you)..it''s graphic, it''s beautiful reminds me of Lewis Hine''s work and I HATE you 10:))', '2005-06-14 05:45:46.000000', NULL, 1),
(1454049, 186910, 37334, '<td valign="top">It''s making me feel seasick:)) Nice image, but perhaps the focus could be sharper (or is that the seasickness making my eyes defocus?:) Gong really close in and getting just some of those bricks with the red and black patterns may have made a great image with more impact? But I still like it.</td>', 'It''s making me feel seasick:)) Nice image, but perhaps the focus could be sharper (or is that the seasickness making my eyes defocus?:) Gong really close in and getting just some of those bricks with the red and black patterns may have made a great image with more impact? But I still like it.', '2005-06-14 05:49:38.000000', NULL, 1),
(1454051, 185443, 37334, '<td valign="top">Brilliant capture! 10</td>', 'Brilliant capture! 10', '2005-06-14 05:50:33.000000', NULL, 1),
(1454064, 186876, 37334, '<td valign="top">I love this 10</td>', 'I love this 10', '2005-06-14 05:57:30.000000', NULL, 1),
(1454068, 186901, 30018, '<td valign="top">This is an outstanding image; one I hope does well in the challenge, even though I know it is already hanging on someone''s bedroom wall.  Very nicely done.  &lt;9&gt;</td>', 'This is an outstanding image; one I hope does well in the challenge, even though I know it is already hanging on someone''s bedroom wall.  Very nicely done.  <9>', '2005-06-14 06:04:39.000000', NULL, 1),
(1454069, 185448, 37334, '<td valign="top">I love the repeating patterns. The shadows and light shapes help create them. Good detail and texture. It''s like an Escher painting;) 8</td>', 'I love the repeating patterns. The shadows and light shapes help create them. Good detail and texture. It''s like an Escher painting;) 8', '2005-06-14 06:04:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1454071, 186765, 37334, '<td valign="top">Good composition. The clours work well together. Lots to look at to hold the attention, keeps the eye moving around the image;) 8</td>', 'Good composition. The clours work well together. Lots to look at to hold the attention, keeps the eye moving around the image;) 8', '2005-06-14 06:06:33.000000', NULL, 1),
(1454072, 186807, 30018, '<td valign="top">Very nice capture, of the rust colors, and the detail in the textures of the steel.  But must of all, I love the colors.  Blue and Orage.  Great combination.  &lt;8&gt;</td>', 'Very nice capture, of the rust colors, and the detail in the textures of the steel.  But must of all, I love the colors.  Blue and Orage.  Great combination.  <8>', '2005-06-14 06:07:10.000000', NULL, 1),
(1454075, 186550, 30018, '<td valign="top">Nice image and nice use of the sepia tones.  I love the textures of the steel and wood together.  Interesting composition.  I hope it does well in the challenge.  Good Luck.  &lt;8&gt;</td>', 'Nice image and nice use of the sepia tones.  I love the textures of the steel and wood together.  Interesting composition.  I hope it does well in the challenge.  Good Luck.  <8>', '2005-06-14 06:08:59.000000', NULL, 1),
(1454077, 186417, 30018, '<td valign="top">A great close-up with lots of different and wonderful textures, from the cold steel to the warmth of the wood, not to mention the angle tracks wrapped around the barbed wire.  This image has very nice tonal quality as well.  Interesting composition, makes my eye want to linger and enjoy.  Very nicely done.  &lt;8&gt;</td>', 'A great close-up with lots of different and wonderful textures, from the cold steel to the warmth of the wood, not to mention the angle tracks wrapped around the barbed wire.  This image has very nice tonal quality as well.  Interesting composition, makes my eye want to linger and enjoy.  Very nicely done.  <8>', '2005-06-14 06:11:27.000000', NULL, 1),
(1454083, 186792, 30018, '<td valign="top">Somehow this almost reminds me of the statue of Iowa Jima.  Very nice silhouette against a beautiful and dramatic sky.  &lt;7&gt;</td>', 'Somehow this almost reminds me of the statue of Iowa Jima.  Very nice silhouette against a beautiful and dramatic sky.  <7>', '2005-06-14 06:14:05.000000', NULL, 1),
(1454123, 186200, 32602, '<td valign="top">Great use of perspective and colour, and the wide shadows add a to the atmosphere.<br/>Good work. Is this a tar cart?</td>', 'Great use of perspective and colour, and the wide shadows add a to the atmosphere.Good work. Is this a tar cart?', '2005-06-14 06:52:40.000000', NULL, 1),
(1454128, 186843, 32602, '<td valign="top">Good use of telescope ; )  <br/>I like the colour and the depth of field is very good, perhaps the point of view could be better angled just to get a bit more of the background earth mover, but that might not have been possible. The title fits the image nicely and it sure does look barren there.</td>', 'Good use of telescope ; )  I like the colour and the depth of field is very good, perhaps the point of view could be better angled just to get a bit more of the background earth mover, but that might not have been possible. The title fits the image nicely and it sure does look barren there.', '2005-06-14 06:59:30.000000', NULL, 1),
(1454132, 186840, 32602, '<td valign="top">This could work well as an abstract if there was a bit more drama, perhaps shooting at a different time of day to capture some shadows would bump up the contrast . I like the use of perspective.</td>', 'This could work well as an abstract if there was a bit more drama, perhaps shooting at a different time of day to capture some shadows would bump up the contrast . I like the use of perspective.', '2005-06-14 07:05:45.000000', NULL, 1),
(1454139, 186565, 32602, '<td valign="top">Nice shot, I like that you captured his involvement and concentration, his eye is on his work and his muscles are flexed. The sun lighting his shirt, the white is well detailed and not blown out, and skin is lovely,  It would have been nice to get a bit more light on his face, but that is not always possible in a candid. I don''t mind the dark background it focuses me on the man. Good capture.</td>', 'Nice shot, I like that you captured his involvement and concentration, his eye is on his work and his muscles are flexed. The sun lighting his shirt, the white is well detailed and not blown out, and skin is lovely,  It would have been nice to get a bit more light on his face, but that is not always possible in a candid. I don''t mind the dark background it focuses me on the man. Good capture.', '2005-06-14 07:19:19.000000', NULL, 1),
(1454141, 185278, 32602, '<td valign="top">The glow over the roof is nice, is it morning or evening? I think this would benefit from a colour boost.</td>', 'The glow over the roof is nice, is it morning or evening? I think this would benefit from a colour boost.', '2005-06-14 07:22:31.000000', NULL, 1),
(1454146, 185713, 32602, '<td valign="top">Good shot, I really like that you''ve captured the attitude (position and expression) of the workman candidly. Works well in b&amp;w.</td>', 'Good shot, I really like that you''ve captured the attitude (position and expression) of the workman candidly. Works well in b&w.', '2005-06-14 07:27:08.000000', NULL, 1),
(1454152, 186826, 35602, '<td valign="top">Beautiful city scape.  Your horizon is in the middle, but because you have the building tops above it, the picture is well balanced.  I am having trouble seeing consttruction, though.  There it is.  I finally spotted the crane  at the left.</td>', 'Beautiful city scape.  Your horizon is in the middle, but because you have the building tops above it, the picture is well balanced.  I am having trouble seeing consttruction, though.  There it is.  I finally spotted the crane  at the left.', '2005-06-14 07:32:47.000000', NULL, 1),
(1454153, 186432, 35602, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2005-06-14 07:33:30.000000', NULL, 1),
(1454155, 185656, 35602, '<td valign="top">Don''t particularly care for the border on this one.  Image needs to be more focused.  Did like your title.  However, I don''t think the gov''t would be letting us see anything of them building a defence system.  They really like to hide everythng.</td>', 'Don''t particularly care for the border on this one.  Image needs to be more focused.  Did like your title.  However, I don''t think the gov''t would be letting us see anything of them building a defence system.  They really like to hide everythng.', '2005-06-14 07:35:31.000000', NULL, 1),
(1454158, 186865, 35602, '<td valign="top">The focus on this one was lacking.  The fact that you tried to balance the lovely light in the upper left with the red in the lower right was a good compostitional choice.  If only it were more focused.</td>', 'The focus on this one was lacking.  The fact that you tried to balance the lovely light in the upper left with the red in the lower right was a good compostitional choice.  If only it were more focused.', '2005-06-14 07:37:08.000000', NULL, 1),
(1454160, 184581, 29474, '<td valign="top">Lovely picture. But I am not sure that it says ''construction''</td>', 'Lovely picture. But I am not sure that it says ''construction''', '2005-06-14 07:39:03.000000', NULL, 1),
(1454171, 186811, 36437, '<td valign="top">Beatyfull artistic shot. I like it!</td>', 'Beatyfull artistic shot. I like it!', '2005-06-14 07:58:19.000000', NULL, 1),
(1454197, 186169, 35548, '<td valign="top">This is a nice image and process very nicely, buit I can not make the connection from photo to challenge description as hard as a may try.</td>', 'This is a nice image and process very nicely, buit I can not make the connection from photo to challenge description as hard as a may try.', '2005-06-14 08:30:28.000000', NULL, 1),
(1454199, 186850, 35548, '<td valign="top">Sad to say I think the image is a result from a recent dpchallenge  challenge of minimalizm....   I don''t think the composition works for this challenge.  Sorry</td>', 'Sad to say I think the image is a result from a recent dpchallenge  challenge of minimalizm....   I don''t think the composition works for this challenge.  Sorry', '2005-06-14 08:32:57.000000', NULL, 1),
(1454214, 186444, 11895, '<td valign="top">I like the concept here but the image is pretty bright.  Try playing with hue/saturation to get more of a separation between the blue paint on the beams and the blue of the sky.</td>', 'I like the concept here but the image is pretty bright.  Try playing with hue/saturation to get more of a separation between the blue paint on the beams and the blue of the sky.', '2005-06-14 08:46:37.000000', NULL, 1),
(1454287, 185870, 11895, '<td valign="top">I like this and have voted it fairly high but I don''t understand why you use a border on such a small picture.</td>', 'I like this and have voted it fairly high but I don''t understand why you use a border on such a small picture.', '2005-06-14 09:36:59.000000', NULL, 1),
(1454341, 186878, 39265, '<td valign="top">I really like the colors, the reflections, and the design - Good luck:)</td>', 'I really like the colors, the reflections, and the design - Good luck:)', '2005-06-14 10:04:02.000000', NULL, 1),
(1454342, 186864, 16241, '<td valign="top">good</td>', 'good', '2005-06-14 10:04:04.000000', NULL, 1),
(1454344, 186687, 16241, '<td valign="top">dramatic, i like it, stands out even in thumbnail</td>', 'dramatic, i like it, stands out even in thumbnail', '2005-06-14 10:05:18.000000', NULL, 1),
(1454345, 184581, 39265, '<td valign="top">I really like the design, the colors, and the idea that it impresses on construction. Great work!</td>', 'I really like the design, the colors, and the idea that it impresses on construction. Great work!', '2005-06-14 10:05:32.000000', NULL, 1),
