(1454933, 186940, 36397, '<td valign="top">Nice picture, a bit dark, I like the angle.</td>', 'Nice picture, a bit dark, I like the angle.', '2005-06-14 14:05:53.000000', NULL, 1),
(1454936, 186840, 36397, '<td valign="top">Nice picture! I like the artistic impression. The colors are a bit light.</td>', 'Nice picture! I like the artistic impression. The colors are a bit light.', '2005-06-14 14:07:11.000000', NULL, 1),
(1454999, 186876, 25111, '<td valign="top">This is one of the top pictures in the bunch, nice tone to give the old look and the pose is good.</td>', 'This is one of the top pictures in the bunch, nice tone to give the old look and the pose is good.', '2005-06-14 14:43:35.000000', NULL, 1),
(1455003, 186811, 16046, '<td valign="top">wonderful, great job</td>', 'wonderful, great job', '2005-06-14 14:48:22.000000', NULL, 1),
(1455011, 186394, 16046, '<td valign="top">Looks like it was taken from that park just above Alki off Calif Ave. my entry has the same crane, but much closer. Nice shot.</td>', 'Looks like it was taken from that park just above Alki off Calif Ave. my entry has the same crane, but much closer. Nice shot.', '2005-06-14 14:56:30.000000', NULL, 1),
(1455013, 186792, 16046, '<td valign="top">perfect for the challenge, nice work 10</td>', 'perfect for the challenge, nice work 10', '2005-06-14 14:57:08.000000', NULL, 1),
