(1455214, 186052, 37544, '<td valign="top">one of my favorites!!!!</td>', 'one of my favorites!!!!', '2005-06-14 16:25:44.000000', NULL, 1),
(1455242, 186880, 38693, '<td valign="top">Simple, but powerful image that conveys the theme in a unique way. I like the earth tones, and the old tools.</td>', 'Simple, but powerful image that conveys the theme in a unique way. I like the earth tones, and the old tools.', '2005-06-14 16:44:09.000000', NULL, 1),
(1455309, 186854, 35548, '<td valign="top">I have seen just about all the cranes that I can take in one challenge, (not your fault)  I like the way you positioned this crane between the posts on each  side.  I think you have the hights rate crane that I have judges, nice work. Bumped to 8</td>', 'I have seen just about all the cranes that I can take in one challenge, (not your fault)  I like the way you positioned this crane between the posts on each  side.  I think you have the hights rate crane that I have judges, nice work. Bumped to 8', '2005-06-14 17:18:19.000000', NULL, 1),
(1455310, 186848, 35602, '<td valign="top">A lot of sun flare on this one, especially right in the center of the house.  When shooting iwith the sun in front of you, you could try shading the lens with your hand to prevent the flare.  Just make sure your hand  isn''t in the shot.</td>', 'A lot of sun flare on this one, especially right in the center of the house.  When shooting iwith the sun in front of you, you could try shading the lens with your hand to prevent the flare.  Just make sure your hand  isn''t in the shot.', '2005-06-14 17:18:37.000000', NULL, 1),
(1455311, 186169, 35602, '<td valign="top">Sorry but the theme of construction fails ne.  However the shot is clear and dettailed.  As a photo with the shallow background, it is really good.</td>', 'Sorry but the theme of construction fails ne.  However the shot is clear and dettailed.  As a photo with the shallow background, it is really good.', '2005-06-14 17:20:01.000000', NULL, 1),
(1455315, 185956, 35602, '<td valign="top">Dramatic sky.  The buildings though seem too dark amd I would have cropped out the left building.</td>', 'Dramatic sky.  The buildings though seem too dark amd I would have cropped out the left building.', '2005-06-14 17:21:30.000000', NULL, 1),
(1455317, 186850, 35602, '<td valign="top">I think the subject is too small for the frame.  It also looks a little out of focus.</td>', 'I think the subject is too small for the frame.  It also looks a little out of focus.', '2005-06-14 17:22:32.000000', NULL, 1),
(1455322, 186774, 35602, '<td valign="top">Nice reflection, but it isn''t strong enough to depict a good representation of the construction aspect of the challenge.</td>', 'Nice reflection, but it isn''t strong enough to depict a good representation of the construction aspect of the challenge.', '2005-06-14 17:23:58.000000', NULL, 1),
(1455350, 186823, 37730, '<td valign="top">Strong compositional movement inwards.  I enjoy the power of your photos.</td>', 'Strong compositional movement inwards.  I enjoy the power of your photos.', '2005-06-14 17:39:28.000000', NULL, 1),
