(1480268, 186876, 31727, '<td valign="top">I really like the photo.</td>', 'I really like the photo.', '2005-06-24 02:15:21.000000', NULL, 0),
(1481560, 186392, 36078, '<td valign="top">I love the idea I just think the lighting was so dark you could not see any deatil.  But lighting is a 2 way street.  Any lighter for me and the houses would have overpowered the cranes.  ou might have been able to just get closer and zoom on the tops of the 2 cranes and then cropped it with the nice clouds behind it.</td>', 'I love the idea I just think the lighting was so dark you could not see any deatil.  But lighting is a 2 way street.  Any lighter for me and the houses would have overpowered the cranes.  ou might have been able to just get closer and zoom on the tops of the 2 cranes and then cropped it with the nice clouds behind it.', '2005-06-24 16:41:03.000000', NULL, 0),
